 3 | pragma solidity ^0.8.17;
 4 | 
 5 | import {ReentrancyGuardUpgradeable} from "ozu/security/ReentrancyGuardUpgradeable.sol";
 6 | import {ERC20Upgradeable, ERC20PermitUpgradeable} from "ozu/token/ERC20/extensions/draft-ERC20PermitUpgradeable.sol";
 7 | import {IERC20, SafeERC20} from "oz/token/ERC20/utils/SafeERC20.sol";
 8 | import {SafeCast} from "oz/utils/math/SafeCast.sol";
 9 | import {IWell, Call} from "src/interfaces/IWell.sol";
10 | import {IWellErrors} from "src/interfaces/IWellErrors.sol";
11 | import {IPump} from "src/interfaces/pumps/IPump.sol";
12 | import {IWellFunction} from "src/interfaces/IWellFunction.sol";
13 | import {LibBytes} from "src/libraries/LibBytes.sol";
14 | import {ClonePlus} from "src/utils/ClonePlus.sol";
15 | 
16 | /**
17 |  * @title Well
18 |  * @author Publius, Silo Chad, Brean
19 |  * @dev A Well is a constant function AMM allowing the provisioning of liquidity
20 |  * into a single pooled on-chain liquidity position.
21 |  */
22 | contract Well is ERC20PermitUpgradeable, IWell, IWellErrors, ReentrancyGuardUpgradeable, ClonePlus {
23 |     using SafeERC20 for IERC20;
24 |     using SafeCast for uint256;
25 | 
26 |     uint256 constant ONE_WORD = 32;
27 |     uint256 constant PACKED_ADDRESS = 20;
28 |     uint256 constant ONE_WORD_PLUS_PACKED_ADDRESS = 52; // For gas efficiency purposes
29 |     bytes32 constant RESERVES_STORAGE_SLOT = bytes32(uint256(keccak256("reserves.storage.slot")) - 1);
30 | 
31 |     function init(string memory name, string memory symbol) public initializer {
32 |         __ERC20Permit_init(name);
33 |         __ERC20_init(name, symbol);
34 | 
35 |         IERC20[] memory _tokens = tokens();
36 |         for (uint256 i; i < _tokens.length - 1; ++i) {
37 |             for (uint256 j = i + 1; j < _tokens.length; ++j) {
38 |                 if (_tokens[i] == _tokens[j]) {
39 |                     revert DuplicateTokens(_tokens[i]);
40 |                 }
41 |             }
42 |         }
43 |     }
44 | 
45 |     //////////////////// WELL DEFINITION ////////////////////
46 | 
47 |     /// This Well uses a dynamic immutable storage layout. Immutable storage is
48 |     /// used for gas-efficient reads during Well operation. The Well must be
49 |     /// created by cloning with a pre-encoded byte string containing immutable
50 |     /// data.
51 |     ///
